capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
shelves = []
shelf_capacities = {}
for rec in capacity_records:
    shelf_id = rec['values']['ShelfID']
    shelves.append(shelf_id)
    shelf_capacities[shelf_id] = int(rec['values']['Capacity'])
products = []
product_values = {}
product_weights = {}
for rec in product_records:
    prod_id = rec['values']['ProductName']
    products.append(prod_id)
    product_values[prod_id] = int(rec['values']['Value'])
    product_weights[prod_id] = int(rec['values']['Weight'])
if len(shelves) != 10:
    raise ValueError('Expected 10 shelves, got %d' % len(shelves))
if len(products) != 20:
    raise ValueError('Expected 20 products, got %d' % len(products))
for sid in shelves:
    if sid not in shelf_capacities:
        raise ValueError(f'Missing capacity for shelf {sid}')
for pid in products:
    if pid not in product_values or pid not in product_weights:
        raise ValueError(f'Missing value/weight for product {pid}')
m = Model()
m.setParam('MIPGap', 0.0001)
x_vars = m.addVars(shelves, products, vtype=GRB.INTEGER, lb=0, name='')
m.setObjective(quicksum((product_values[j] * x_vars[i, j] for i in shelves for j in products)), GRB.MAXIMIZE)
for i in shelves:
    m.addConstr(quicksum((product_weights[j] * x_vars[i, j] for j in products)) <= shelf_capacities[i], name=f'cap_{i}')
m.optimize()
if m.Status == GRB.OPTIMAL:
    print('ObjVal:', m.ObjVal)
    for i in shelves:
        for j in products:
            v = x_vars[i, j]
            print(f'{v.VarName} {v.X}')
else:
